    const malformedOwner: Record<string, unknown> = { format: "future-lock", formatVersion: 2, operationId: "bad operation", identityKind: "invalid-kind", identityKey: "", nonce: "z".repeat(32), generation: "z".repeat(32), pid: 0, processToken: "", acquiredAt: "not-a-time", heartbeatAt: "not-a-time" };
    for (const [key, invalid] of Object.entries(malformedOwner)) { await writeCanonical(ownerFile, { ...owner, [key]: invalid }); const result = await validateLifecycleLockLease(store, held, "parser"); expect(result, `owner.malformed.${key}`).toMatchObject({ ok: false, code: "lost-lock" }); expect(JSON.stringify(result)).not.toContain("CANARY"); await fs.writeFile(ownerFile, ownerOriginal); }
