    const predecessor = { kind: owner.identityKind, key: owner.identityKey, nonce: "1".repeat(32), generation: "2".repeat(32) }; await writeCanonical(ownerFile, { ...owner, predecessorBinding: predecessor }); expect(await validateLifecycleLockLease(store, held, "parser")).toMatchObject({ ok: true }); expect(await heartbeatLifecycleLocks(held)).toMatchObject({ ok: true }); const heartbeaten = JSON.parse(await fs.readFile(ownerFile, "utf8")) as Record<string, unknown>; expect(heartbeaten.predecessorBinding).toEqual(predecessor);
    const predecessorMutations: readonly (readonly [string, unknown])[] = [["missing-kind", { key: predecessor.key, nonce: predecessor.nonce, generation: predecessor.generation }], ["missing-key", { kind: predecessor.kind, nonce: predecessor.nonce, generation: predecessor.generation }], ["missing-nonce", { kind: predecessor.kind, key: predecessor.key, generation: predecessor.generation }], ["missing-generation", { kind: predecessor.kind, key: predecessor.key, nonce: predecessor.nonce }], ["extra", { ...predecessor, extra: "PREDECESSOR_EXTRA_CANARY" }], ["malformed", "PREDECESSOR_MALFORMED_CANARY"], ["wrong-kind", { ...predecessor, kind: "settings" }], ["wrong-key", { ...predecessor, key: "PREDECESSOR_WRONG_IDENTITY_CANARY" }], ["bad-nonce", { ...predecessor, nonce: "z".repeat(32) }], ["bad-generation", { ...predecessor, generation: "z".repeat(32) }], ["self", { kind: owner.identityKind, key: owner.identityKey, nonce: owner.nonce, generation: owner.generation }]];
