    await fs.writeFile(ownerFile, Buffer.concat([Buffer.from((canonicalJsonBytes(heartbeaten) as { ok: true; value: Uint8Array }).value), Buffer.from("\n")])); expect(await validateLifecycleLockLease(store, held, "parser")).toMatchObject({ ok: false, code: "lost-lock" }); await writeCanonical(ownerFile, heartbeaten);
    for (const authoritative of [receiptFile, journalFile, ...lockVector(store).map((identity) => path.join(lifecycleLockDirectory(store, identity), "owner.json"))]) { const content = await fs.readFile(authoritative).catch(() => Buffer.alloc(0)); expect(content.toString(), authoritative).not.toContain("CANARY"); } expect(await releaseLifecycleLocks(held)).toMatchObject({ ok: true });
