  it("detects forged/released leases, fixed-order contention, stale heartbeat identity, and invalid partial requests", async () => {
    const store = await fixture(); const held = await lease(store, "locks"); expect(await validateLifecycleLockLease(store, { ...held }, "locks")).toMatchObject({ ok: false, code: "invalid-lease" }); expect((await heartbeatLifecycleLocks(held)).ok).toBe(true);
    expect(await acquireLifecycleLocks({ store, operationId: "other", identities: [{ kind: "profile", key: store.profileKey }] })).toMatchObject({ ok: false, code: "lock-busy" });
    expect(await acquireLifecycleLocks({ store, operationId: "partial", identities: [{ kind: "profile", key: "wrong-profile" }, { kind: "settings", key: "x" }] })).toMatchObject({ ok: false, code: "invalid-lock-order" });
    expect(await releaseLifecycleLocks(held)).toMatchObject({ ok: true }); expect(await validateLifecycleLockLease(store, held, "locks")).toMatchObject({ ok: false, code: "invalid-lease" });
    const collision = lifecycleLockDirectory(store, lockVector(store)[1]!); await fs.mkdir(collision); await fs.writeFile(path.join(collision, "owner.json"), "{}"); const contenderBytes = await fs.readFile(path.join(collision, "owner.json"));
    expect(await acquireLifecycleLocks({ store, operationId: "partial-cleanup", identities: lockVector(store) })).toMatchObject({ ok: false, code: "ambiguous-lock" });
    await expect(fs.stat(lifecycleLockDirectory(store, lockVector(store)[0]!))).rejects.toMatchObject({ code: "ENOENT" }); expect(await fs.readFile(path.join(collision, "owner.json"))).toEqual(contenderBytes); await fs.rm(collision, { recursive: true });
  });

  it("reports lost-lock on heartbeat ownership mutation and preserves replacement bytes", async () => {
    const store = await fixture(); const held = await lease(store, "heartbeat-identity-change"); const directory = lifecycleLockDirectory(store, lockVector(store)[0]!); const ownerFile = path.join(directory, "owner.json"); const owner = JSON.parse(await fs.readFile(ownerFile, "utf8")) as Record<string, unknown>; const replacement = canonicalJsonBytes({ ...owner, nonce: "0".repeat(32) }); if (!replacement.ok) throw new Error(replacement.message); await fs.writeFile(ownerFile, replacement.value); const entries = await fs.readdir(directory);
    expect(await heartbeatLifecycleLocks(held)).toMatchObject({ ok: false, code: "lost-lock" }); expect(await fs.readFile(ownerFile)).toEqual(Buffer.from(replacement.value)); expect(await fs.readdir(directory)).toEqual(entries);
  });

  it("reports lost-lock on release directory replacement and preserves replacement ownership", async () => {
    const store = await fixture(); const held = await lease(store, "release-identity-change"); const directory = lifecycleLockDirectory(store, lockVector(store)[0]!); const displaced = `${directory}.displaced`; const originalOwner = JSON.parse(await fs.readFile(path.join(directory, "owner.json"), "utf8")) as Record<string, unknown>; const replacement = canonicalJsonBytes({ ...originalOwner, generation: "0".repeat(32) }); if (!replacement.ok) throw new Error(replacement.message); await fs.rename(directory, displaced); await fs.mkdir(directory); await fs.writeFile(path.join(directory, "owner.json"), replacement.value); const entries = await fs.readdir(directory);
    expect(await releaseLifecycleLocks(held)).toMatchObject({ ok: false, code: "lost-lock" }); expect(await fs.readFile(path.join(directory, "owner.json"))).toEqual(Buffer.from(replacement.value)); expect(await fs.readdir(directory)).toEqual(entries); expect(await exists(displaced)).toBe(true);
  });

  it("proves repeated crash-window takeover, recovery, and receipt truth with exactly three bounded launches", async () => {
    const base = await fs.mkdtemp(path.join(os.tmpdir(), "picc-fresh-")); roots.push(base); if (process.platform !== "win32") await fs.chmod(base, 0o700); const profile = path.join(base, "profile");
    const pendingScript = String.raw`
      import { promises as fs } from "node:fs"; import path from "node:path";
      import { createLifecycleLocations } from "./src/plugin-lifecycle/locations.ts";
      import { establishOwnedStateStore, ownedRecordPartition, sha256 } from "./src/plugin-lifecycle/state-store.ts";
      import { acquireLifecycleLocks } from "./src/plugin-lifecycle/locks.ts";
      import { prepareTransaction, executeTransaction } from "./src/plugin-lifecycle/transaction.ts";
      const locations=createLifecycleLocations({homeDir:process.env.HOME_DIR,profilePath:process.env.PROFILE_DIR,platform:process.platform==="win32"?"win32":"posix"}); if(!locations.ok) throw Error("locations");
      const established=await establishOwnedStateStore(locations.value,process.env.HOME_DIR); if(!established.ok) throw Error(established.message); const store=established.value;
      const partition=ownedRecordPartition(store,"producer","user"); if(!partition.ok) throw Error(partition.message); await fs.mkdir(partition.value,{recursive:true,mode:0o700});
      const bytes=Buffer.from("fresh"); const staged=path.join(store.stagingRoot,"fresh.stage"); await fs.writeFile(staged,bytes,{flag:"wx",mode:0o600});
      const requiredLocks=(_s,ps)=>({ok:true,value:[{kind:"profile",key:path.basename(path.dirname(path.dirname(ps[0].stagedPath)))},{kind:"checkout",key:"checkout-main"},{kind:"settings",key:"settings-user"}]});
      const codec={schema:"test.transaction",version:1,decodeSummary:v=>({ok:true,value:v}),validatePlan:()=>({ok:true,value:undefined}),requiredLocks};
      const made=await prepareTransaction({store,codec,operationId:"fresh-op",confirmationSummary:{label:"fresh-op"},participants:[{kind:"test.record",key:"fresh",ownerKey:"producer",scopeKey:"user",targetPath:path.join(partition.value,"fresh.json"),targetClass:"owned",precondition:{state:"absent"},stagedPath:staged,stagedDigest:sha256(bytes),rollback:{kind:"delete-new-target"},producerEvidence:{key:"fresh"}}]}); if(!made.ok) throw Error(made.message);
      const locked=await acquireLifecycleLocks({store,operationId:"fresh-op",identities:requiredLocks(null,made.value.participants).value}); if(!locked.ok) throw Error(locked.message);
      const outcome=await executeTransaction(store,made.value,{lease:locked.value,faults:{hit(phase){if(phase==="after-replacement") throw Error("stop");}}}); process.stdout.write(JSON.stringify(outcome));
    `;
    let childLaunches = 0;
    async function child(script: string): Promise<string> {
      childLaunches += 1; const launched = spawn(process.execPath, ["--import", "tsx", "--input-type=module", "-e", script], { cwd: process.cwd(), env: { ...process.env, HOME_DIR: base, PROFILE_DIR: profile }, stdio: ["ignore", "pipe", "pipe"] }); let stdout = ""; let stderr = ""; launched.stdout.on("data", (chunk: Buffer) => { stdout += chunk.toString(); }); launched.stderr.on("data", (chunk: Buffer) => { stderr += chunk.toString(); });
      const exit = new Promise<void>((resolve, reject) => { launched.once("error", reject); launched.once("exit", (code) => code === 0 ? resolve() : reject(new Error(`child ${code}: ${stderr}`))); }); const ceiling = setTimeout(() => launched.kill(), 10_000); try { await exit; return stdout; } finally { clearTimeout(ceiling); if (launched.exitCode === null) launched.kill(); await new Promise<void>((resolve) => launched.exitCode === null ? launched.once("exit", () => resolve()) : resolve()); }
    }
    expect(JSON.parse(await child(pendingScript))).toMatchObject({ state: "pending-recovery", completed: 1 });
    const locations = createLifecycleLocations({ homeDir: base, profilePath: profile, platform: process.platform === "win32" ? "win32" : "posix" }); if (!locations.ok) throw new Error("locations"); const established = await establishOwnedStateStore(locations.value, base); if (!established.ok) throw new Error(established.message); const store = established.value;
    const pending = await previewRecovery({ store, operationId: "fresh-op", registry: registry() }); expect(pending).toMatchObject({ ok: true, value: { completed: 1 } }); if (!pending.ok) return; const journalBeforeTakeover = await readTransactionJournal(store, "fresh-op"); if (!journalBeforeTakeover.ok) throw new Error(journalBeforeTakeover.message); const originalBindings = journalBeforeTakeover.value.lockBindings;
    const takeoverScript = String.raw`
      import { createLifecycleLocations } from "./src/plugin-lifecycle/locations.ts"; import { establishOwnedStateStore } from "./src/plugin-lifecycle/state-store.ts"; import { acquireLifecycleLocks } from "./src/plugin-lifecycle/locks.ts";
      const l=createLifecycleLocations({homeDir:process.env.HOME_DIR,profilePath:process.env.PROFILE_DIR,platform:process.platform==="win32"?"win32":"posix"}); if(!l.ok) throw Error("locations"); const s=await establishOwnedStateStore(l.value,process.env.HOME_DIR); if(!s.ok) throw Error(s.message);
      const identities=[{kind:"profile",key:s.value.profileKey},{kind:"checkout",key:"checkout-main"},{kind:"settings",key:"settings-user"}]; const taken=await acquireLifecycleLocks({store:s.value,operationId:"fresh-op",identities,expectedRecoveryOperationId:"fresh-op"}); if(!taken.ok) throw Error(taken.code+":"+taken.message); process.stdout.write(JSON.stringify(taken.value.bindings));
    `;
    const childBindings = JSON.parse(await child(takeoverScript)) as unknown[]; expect(childBindings).toHaveLength(3); const replacementOwners = await Promise.all(lockVector(store).map((identity) => fs.readFile(path.join(lifecycleLockDirectory(store, identity), "owner.json"), "utf8").then((value) => JSON.parse(value) as Record<string, unknown>))); expect(replacementOwners.map((owner) => owner.predecessorBinding)).toEqual(originalBindings); expect(replacementOwners.map((owner) => ({ kind: owner.identityKind, key: owner.identityKey, nonce: owner.nonce, generation: owner.generation }))).toEqual(childBindings);
    const recoveryBase = { store, operationId: "fresh-op", expectedRecoveryOperationId: "fresh-op", processProbe: { observe: async () => ({ state: "absent" as const }) } };
    expect(await acquireLifecycleLocks({ ...recoveryBase, identities: lockVector(store).slice(0, 2) })).toMatchObject({ ok: false, code: "ambiguous-lock" });
    expect(await acquireLifecycleLocks({ ...recoveryBase, identities: [lockVector(store)[0]!, lockVector(store)[1]!, { kind: "settings", key: "wrong" }] })).toMatchObject({ ok: false, code: "ambiguous-lock" });
    expect(await acquireLifecycleLocks({ ...recoveryBase, identities: [lockVector(store)[0]!, lockVector(store)[2]!, lockVector(store)[1]!] })).toMatchObject({ ok: false, code: "invalid-lock-order" });
    expect(await acquireLifecycleLocks({ ...recoveryBase, identities: lockVector(store), processProbe: { observe: async () => ({ state: "live" as const, processToken: "reused" }) } })).toMatchObject({ ok: false, code: "ambiguous-lock" });
    expect(await acquireLifecycleLocks({ ...recoveryBase, identities: lockVector(store), processProbe: { observe: async () => ({ state: "ambiguous" as const, reason: "unknown" }) } })).toMatchObject({ ok: false, code: "ambiguous-lock" });
    const profileOwner = path.join(lifecycleLockDirectory(store, lockVector(store)[0]!), "owner.json"); const ownerBytes = await fs.readFile(profileOwner); const owner = JSON.parse(ownerBytes.toString()) as Record<string, unknown>; const missingPredecessor = { ...owner }; delete missingPredecessor.predecessorBinding; const missingBytes = canonicalJsonBytes(missingPredecessor); if (!missingBytes.ok) throw new Error(missingBytes.message); await fs.writeFile(profileOwner, missingBytes.value); expect(await acquireLifecycleLocks({ ...recoveryBase, identities: lockVector(store) })).toMatchObject({ ok: false, code: "ambiguous-lock" }); await fs.writeFile(profileOwner, ownerBytes);
    const wrongOwner = canonicalJsonBytes({ ...owner, nonce: "0".repeat(32), predecessorBinding: { ...(owner.predecessorBinding as Record<string, unknown>), nonce: "0".repeat(32) } }); if (!wrongOwner.ok) throw new Error(wrongOwner.message); await fs.writeFile(profileOwner, wrongOwner.value);
    const wrongResult = await acquireLifecycleLocks({ ...recoveryBase, identities: lockVector(store) }); expect(wrongResult).toMatchObject({ ok: false, code: "ambiguous-lock" }); expect(JSON.stringify(wrongResult)).not.toContain("CANARY"); await fs.writeFile(profileOwner, ownerBytes);
    const journalFile = path.join(store.journalsRoot, "fresh-op.json"); const journalBytes = await fs.readFile(journalFile); await fs.writeFile(journalFile, "{}"); expect(await acquireLifecycleLocks({ ...recoveryBase, identities: lockVector(store) })).toMatchObject({ ok: false, code: "ambiguous-lock" }); await fs.writeFile(journalFile, journalBytes);
    const lockDirectories = lockVector(store).map((identity) => lifecycleLockDirectory(store, identity)); const ownerFiles = lockDirectories.map((directory) => path.join(directory, "owner.json")); const exactOldVector = await Promise.all(ownerFiles.map((candidate) => fs.readFile(candidate))); const exactOldIdentities = await Promise.all(lockDirectories.map(async (directory) => { const stat = await fs.lstat(directory, { bigint: true }); return { dev: stat.dev, ino: stat.ino }; })); let probeCalls = 0;
    expect(await acquireLifecycleLocks({ ...recoveryBase, identities: lockVector(store), processProbe: { observe: async () => { probeCalls += 1; return probeCalls === 5 ? { state: "ambiguous" as const, reason: "deterministic later-member failure" } : { state: "absent" as const }; } } })).toMatchObject({ ok: false, code: "ambiguous-lock" }); expect(probeCalls).toBe(5); expect(await Promise.all(ownerFiles.map((candidate) => fs.readFile(candidate)))).toEqual(exactOldVector); expect(await Promise.all(lockDirectories.map(async (directory) => { const stat = await fs.lstat(directory, { bigint: true }); return { dev: stat.dev, ino: stat.ino }; }))).toEqual(exactOldIdentities);
    const takeover = await acquireLifecycleLocks({ store, operationId: "fresh-op", identities: lockVector(store), expectedRecoveryOperationId: "fresh-op" }); if (!takeover.ok) throw new Error(`${takeover.code}: ${takeover.message}`); const repeatedOwners = await Promise.all(lockVector(store).map((identity) => fs.readFile(path.join(lifecycleLockDirectory(store, identity), "owner.json"), "utf8").then((value) => JSON.parse(value) as Record<string, unknown>))); expect(repeatedOwners.map((owner) => owner.predecessorBinding)).toEqual(originalBindings); expect(repeatedOwners.map((owner) => ({ kind: owner.identityKind, key: owner.identityKey, nonce: owner.nonce, generation: owner.generation }))).toEqual(takeover.value.bindings);
    expect(await recoverTransaction({ store, operationId: "fresh-op", action: "complete", confirmedProducerSchema: "test.transaction", confirmedProducerVersion: 1, confirmedPlanDigest: pending.value.planDigest, confirmedConfirmationDigest: pending.value.confirmationDigest, registry: registry(), lease: takeover.value })).toMatchObject({ ok: true, value: { outcome: "committed" } }); expect(await acquireLifecycleLocks({ ...recoveryBase, identities: lockVector(store) })).toMatchObject({ ok: false, code: "ambiguous-lock" }); await releaseLifecycleLocks(takeover.value);
    const receiptScript = String.raw`import { createLifecycleLocations } from "./src/plugin-lifecycle/locations.ts"; import { establishOwnedStateStore } from "./src/plugin-lifecycle/state-store.ts"; import { readTransactionReceipt } from "./src/plugin-lifecycle/transaction.ts"; const l=createLifecycleLocations({homeDir:process.env.HOME_DIR,profilePath:process.env.PROFILE_DIR,platform:process.platform==="win32"?"win32":"posix"}); if(!l.ok) throw Error("locations"); const s=await establishOwnedStateStore(l.value,process.env.HOME_DIR); if(!s.ok) throw Error(s.message); process.stdout.write(JSON.stringify(await readTransactionReceipt(s.value,"fresh-op")));`;
    expect(JSON.parse(await child(receiptScript))).toMatchObject({ ok: true, value: { outcome: "committed", completed: 1 } }); expect(childLaunches).toBe(3);
  }, 20_000);

  it("keeps stored receipt truth when rendering and fallback output fail", async () => {
    const store = await fixture(); const plan = await prepared(store, "render", [await participant(store, "render", "ok")]); const held = await lease(store, "render"); let fallback = 0;
    expect(await executeTransaction(store, plan, { lease: held, onOutcome: () => { throw new Error("renderer"); }, fallbackOutput: () => { fallback += 1; throw new Error("output"); } })).toMatchObject({ state: "committed" }); expect(fallback).toBe(1); expect(await readTransactionReceipt(store, "render")).toMatchObject({ ok: true, value: { outcome: "committed" } }); await releaseLifecycleLocks(held);
  });
